WITH exploded AS (SELECT id, service, level, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS attr_key, value), base AS (SELECT id, service, latency_ms, status_code, attr_key, value, UPPER(service) AS service_upper, TRIM(service) AS clean_service FROM exploded WHERE attr_key IS NOT NULL AND service = 'billing'), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY service ORDER BY latency_ms ASC NULLS LAST, id ASC, attr_key ASC) AS rn FROM base) t WHERE rn = 1), cleaned AS (SELECT *, CAST(latency_ms AS STRING) AS latency_ms_str, CEIL(status_code) AS status_code_whole, COALESCE(attr_key, 'DIRECT') AS attr_key_filled FROM ranked WHERE attr_key IS NOT NULL), cleaned_app_logs AS (SELECT id, service, latency_ms, status_code, attr_key, value, service_upper, rn, status_code_whole, LENGTH(attr_key) AS attr_key_length, COALESCE(attr_key, 'N/A') AS resolved_attr_key FROM cleaned WHERE latency_ms != 1838), enriched AS (SELECT *, STDDEV_SAMP(status_code_whole) OVER (PARTITION BY service, attr_key) AS service_stddev_samp_status_code_whole, SUM(status_code) OVER (PARTITION BY service ORDER BY status_code ASC, id ASC, attr_key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_code FROM cleaned_app_logs WHERE attr_key != 'trace') SELECT id, service, latency_ms, status_code, attr_key, value, rn, status_code_whole, attr_key_length FROM enriched ORDER BY attr_key_length DESC, rn ASC
